// MARK: - Logging

enum AlmadarThemeLog {
    /// Never a silent default: every unparseable (non-nil) CSS value logs
    /// here before the caller substitutes the fallback.
    static func warn(_ message: String) {
        print("[AlmadarTheme] WARNING: \(message)")
    }
}

// MARK: - Deterministic CSS-value parsers

enum AlmadarThemeParse {
    static func isUnresolvedVarRef(_ raw: String) -> Bool {
        raw.hasPrefix("var(")
    }

    static func color(_ raw: String?, fallback: Color) -> Color {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("color: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        if raw == "transparent" { return Color.clear }
        if raw.hasPrefix("#"), let c = parseHexColor(raw) { return c }
        if raw.hasPrefix("rgb"), let c = parseRgbColor(raw) { return c }
        if raw.hasPrefix("hsl"), let c = parseHslColor(raw) { return c }
        AlmadarThemeLog.warn("color: unparseable value \"\(raw)\"")
        return fallback
    }

    private static func parseHexColor(_ raw: String) -> Color? {
        var hex = raw.trimmingCharacters(in: .whitespaces)
        hex.removeFirst()
        guard hex.allSatisfy({ $0.isHexDigit }) else { return nil }
        var r: UInt64 = 0, g: UInt64 = 0, b: UInt64 = 0, a: UInt64 = 255
        switch hex.count {
        case 3:
            let chars = Array(hex)
            hex = chars.map { String([$0, $0]) }.joined()
            fallthrough
        case 6:
            guard let v = UInt64(hex, radix: 16) else { return nil }
            r = (v >> 16) & 0xFF; g = (v >> 8) & 0xFF; b = v & 0xFF
        case 8:
            guard let v = UInt64(hex, radix: 16) else { return nil }
            r = (v >> 24) & 0xFF; g = (v >> 16) & 0xFF; b = (v >> 8) & 0xFF; a = v & 0xFF
        default:
            return nil
        }
        return Color(.sRGB, red: Double(r) / 255, green: Double(g) / 255, blue: Double(b) / 255, opacity: Double(a) / 255)
    }

    private static func numericComponents(_ raw: String) -> [Double]? {
        guard let open = raw.firstIndex(of: "("), let close = raw.lastIndex(of: ")") else { return nil }
        let inner = raw[raw.index(after: open)..<close]
        let parts = inner.split(separator: ",").map { $0.trimmingCharacters(in: .whitespaces) }
        var out: [Double] = []
        for p in parts {
            let cleaned = p.hasSuffix("%") ? String(p.dropLast()) : p
            guard let v = Double(cleaned) else { return nil }
            out.append(v)
        }
        return out
    }

    private static func parseRgbColor(_ raw: String) -> Color? {
        guard let c = numericComponents(raw), c.count >= 3 else { return nil }
        let alpha = c.count >= 4 ? c[3] : 1.0
        return Color(.sRGB, red: c[0] / 255, green: c[1] / 255, blue: c[2] / 255, opacity: alpha)
    }

    private static func parseHslColor(_ raw: String) -> Color? {
        guard let c = numericComponents(raw), c.count >= 3 else { return nil }
        let alpha = c.count >= 4 ? c[3] : 1.0
        let h = c[0] / 360, s = c[1] / 100, l = c[2] / 100
        return Color(hue: h, saturation: s, brightness: l <= 0.5 ? l * (1 + s) : l + s - l * s, opacity: alpha)
    }

    static func length(_ raw: String?, fallback: CGFloat) -> CGFloat {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("length: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        if raw.hasSuffix("px"), let n = Double(raw.dropLast(2)) { return CGFloat(n) }
        if raw.hasSuffix("rem"), let n = Double(raw.dropLast(3)) { return CGFloat(n * 16) }
        if let n = Double(raw) { return CGFloat(n) }
        AlmadarThemeLog.warn("length: unparseable value \"\(raw)\"")
        return fallback
    }

    static func number(_ raw: String?, fallback: Double) -> Double {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("number: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        if let n = Double(raw) { return n }
        AlmadarThemeLog.warn("number: unparseable value \"\(raw)\"")
        return fallback
    }

    /// Seconds, matching SwiftUI `Animation` durations.
    static func duration(_ raw: String?, fallback: Double) -> Double {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("duration: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        if raw.hasSuffix("ms"), let n = Double(raw.dropLast(2)) { return n / 1000 }
        if raw.hasSuffix("s"), let n = Double(raw.dropLast(1)) { return n }
        if let n = Double(raw) { return n / 1000 }
        AlmadarThemeLog.warn("duration: unparseable value \"\(raw)\"")
        return fallback
    }

    static func easing(_ raw: String?, fallback: AlmadarTheme.MotionScale.Curve) -> AlmadarTheme.MotionScale.Curve {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("easing: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        switch raw {
        case "linear": return .init(x1: 0, y1: 0, x2: 1, y2: 1)
        case "ease": return .init(x1: 0.25, y1: 0.1, x2: 0.25, y2: 1)
        case "ease-in": return .init(x1: 0.42, y1: 0, x2: 1, y2: 1)
        case "ease-out": return .init(x1: 0, y1: 0, x2: 0.58, y2: 1)
        case "ease-in-out": return .init(x1: 0.42, y1: 0, x2: 0.58, y2: 1)
        default: break
        }
        if raw.hasPrefix("cubic-bezier("), let c = numericComponents(raw), c.count == 4 {
            return .init(x1: c[0], y1: c[1], x2: c[2], y2: c[3])
        }
        AlmadarThemeLog.warn("easing: unparseable value \"\(raw)\"")
        return fallback
    }

    static func splitTopLevel(_ raw: String, separator: Character) -> [String] {
        var parts: [String] = []
        var depth = 0
        var current = ""
        for ch in raw {
            if ch == "(" { depth += 1 } else if ch == ")" { depth -= 1 }
            if ch == separator && depth == 0 {
                parts.append(current)
                current = ""
            } else {
                current.append(ch)
            }
        }
        parts.append(current)
        return parts.map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty }
    }

    private static func lengthValue(_ t: String) -> CGFloat? {
        if t.hasSuffix("px"), let n = Double(t.dropLast(2)) { return CGFloat(n) }
        if t.hasSuffix("rem"), let n = Double(t.dropLast(3)) { return CGFloat(n * 16) }
        if let n = Double(t) { return CGFloat(n) }
        return nil
    }

    private static func strictColor(_ t: String) -> Color? {
        if t == "transparent" { return Color.clear }
        if t.hasPrefix("#") { return parseHexColor(t) }
        if t.hasPrefix("rgb") { return parseRgbColor(t) }
        if t.hasPrefix("hsl") { return parseHslColor(t) }
        return nil
    }

    private static func shadowLayer(_ raw: String, defaultColor: Color) -> AlmadarTheme.ElevationScale.Shadow? {
        var lengths: [CGFloat] = []
        var layerColor: Color?
        var inset = false
        for t in splitTopLevel(raw, separator: " ") {
            if t == "inset" { inset = true; continue }
            if let n = lengthValue(t) { lengths.append(n); continue }
            if let c = strictColor(t) { layerColor = c; continue }
            return nil
        }
        guard lengths.count >= 2, lengths.count <= 4 else { return nil }
        return AlmadarTheme.ElevationScale.Shadow(
            color: layerColor ?? defaultColor,
            radius: lengths.count >= 3 ? lengths[2] : 0,
            x: lengths[0],
            y: lengths[1],
            spread: lengths.count == 4 ? lengths[3] : 0,
            inset: inset
        )
    }

    private static func shadowLayers(_ raw: String, defaultColor: Color) -> AlmadarTheme.ElevationScale.Shadow? {
        let layers = splitTopLevel(raw, separator: ",").map { shadowLayer($0, defaultColor: defaultColor) }
        guard !layers.isEmpty, layers.allSatisfy({ $0 != nil }) else { return nil }
        var head = layers[0]!
        head.underlays = layers.dropFirst().map { $0! }
        return head
    }

    /// `var(--shadow-<key>)` resolves against the theme's own legacy `shadows` map (the
    /// same table the web cascade reads); any other value passes through unchanged.
    static func resolveShadowRef(_ raw: String?, _ shadows: [String: String]?) -> String? {
        guard let raw = raw, raw.hasPrefix("var(--shadow-"), raw.hasSuffix(")") else { return raw }
        let key = String(raw.dropFirst("var(--shadow-".count).dropLast())
        return shadows?[key] ?? raw
    }

    /// `var(--radius-<key>)` resolves against the theme's own legacy `radii` map (the same
    /// table the web cascade reads); any other value passes through unchanged.
    static func resolveRadiusRef(_ raw: String?, _ radii: [String: String]?) -> String? {
        guard let raw = raw, raw.hasPrefix("var(--radius-"), raw.hasSuffix(")") else { return raw }
        let key = String(raw.dropFirst("var(--radius-".count).dropLast())
        return radii?[key] ?? raw
    }

    static func shadow(_ raw: String?, fallback: AlmadarTheme.ElevationScale.Shadow) -> AlmadarTheme.ElevationScale.Shadow {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("shadow: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        if raw == "none" { return AlmadarTheme.ElevationScale.Shadow(color: Color.clear, radius: 0, x: 0, y: 0) }
        if let parsed = shadowLayers(raw, defaultColor: fallback.color) { return parsed }
        AlmadarThemeLog.warn("shadow: unparseable value \"\(raw)\"")
        return fallback
    }

    /// CSS text-shadow: `none` is nil; layers beyond the first ride `underlays`.
    static func textShadow(_ raw: String?, fallback: AlmadarTheme.ElevationScale.Shadow?) -> AlmadarTheme.ElevationScale.Shadow? {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("textShadow: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        if raw == "none" { return nil }
        if let parsed = shadowLayers(raw, defaultColor: Color.black) { return parsed }
        AlmadarThemeLog.warn("textShadow: unparseable value \"\(raw)\"")
        return fallback
    }

    static func cornerShape(_ raw: String?, fallback: AlmadarTheme.CornerShape) -> AlmadarTheme.CornerShape {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("cornerShape: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        switch raw {
        case "round": return .round
        case "squircle": return .squircle
        case "bevel": return .bevel
        case "scoop": return .scoop
        case "notch": return .notch
        default: break
        }
        if raw.hasPrefix("superellipse("), let c = numericComponents(raw), c.count == 1 { return .superellipse(c[0]) }
        AlmadarThemeLog.warn("cornerShape: unparseable value \"\(raw)\"")
        return fallback
    }

    static func borderStyle(_ raw: String?, fallback: AlmadarTheme.BorderLineStyle) -> AlmadarTheme.BorderLineStyle {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("borderStyle: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        if let s = AlmadarTheme.BorderLineStyle(rawValue: raw) { return s }
        AlmadarThemeLog.warn("borderStyle: unparseable value \"\(raw)\"")
        return fallback
    }

    static func textTransform(_ raw: String?, fallback: AlmadarTheme.TextTransform) -> AlmadarTheme.TextTransform {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("textTransform: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        if let s = AlmadarTheme.TextTransform(rawValue: raw) { return s }
        AlmadarThemeLog.warn("textTransform: unparseable value \"\(raw)\"")
        return fallback
    }

    static func fontSlant(_ raw: String?, fallback: AlmadarTheme.FontSlant) -> AlmadarTheme.FontSlant {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("fontSlant: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        if let s = AlmadarTheme.FontSlant(rawValue: raw) { return s }
        AlmadarThemeLog.warn("fontSlant: unparseable value \"\(raw)\"")
        return fallback
    }

    /// CSS font-weight (`normal`, `bold` or 1...1000) bucketed to the nearest SwiftUI weight.
    static func fontWeight(_ raw: String?, fallback: Font.Weight) -> Font.Weight {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("fontWeight: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        if raw == "normal" { return .regular }
        if raw == "bold" { return .bold }
        if let n = Double(raw), n >= 1, n <= 1000 {
            switch n {
            case ..<150: return .ultraLight
            case ..<250: return .thin
            case ..<350: return .light
            case ..<450: return .regular
            case ..<550: return .medium
            case ..<650: return .semibold
            case ..<750: return .bold
            case ..<850: return .heavy
            default: return .black
            }
        }
        AlmadarThemeLog.warn("fontWeight: unparseable value \"\(raw)\"")
        return fallback
    }

    static func tracking(_ raw: String?, fallback: AlmadarTheme.Tracking) -> AlmadarTheme.Tracking {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("tracking: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        if raw == "normal" { return AlmadarTheme.Tracking(value: 0, isEm: true) }
        if raw.hasSuffix("rem"), let n = Double(raw.dropLast(3)) { return AlmadarTheme.Tracking(value: n * 16, isEm: false) }
        if raw.hasSuffix("em"), let n = Double(raw.dropLast(2)) { return AlmadarTheme.Tracking(value: n, isEm: true) }
        if raw.hasSuffix("px"), let n = Double(raw.dropLast(2)) { return AlmadarTheme.Tracking(value: n, isEm: false) }
        if let n = Double(raw), n == 0 { return AlmadarTheme.Tracking(value: 0, isEm: true) }
        AlmadarThemeLog.warn("tracking: unparseable value \"\(raw)\"")
        return fallback
    }

    /// CSS backdrop-filter limited to `blur(<length>)` and `saturate(<n|%>)`; `none` is nil.
    static func backdrop(_ raw: String?, fallback: AlmadarTheme.Backdrop?) -> AlmadarTheme.Backdrop? {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("backdrop: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        if raw == "none" { return nil }
        var blur: CGFloat = 0
        var saturation = 1.0
        for t in splitTopLevel(raw, separator: " ") {
            guard let open = t.firstIndex(of: "("), t.hasSuffix(")") else {
                AlmadarThemeLog.warn("backdrop: unparseable value \"\(raw)\"")
                return fallback
            }
            let name = t[t.startIndex..<open]
            let arg = String(t[t.index(after: open)..<t.index(before: t.endIndex)])
            if name == "blur", let n = lengthValue(arg) { blur = n; continue }
            if name == "saturate" {
                if arg.hasSuffix("%"), let n = Double(arg.dropLast()) { saturation = n / 100; continue }
                if let n = Double(arg) { saturation = n; continue }
            }
            AlmadarThemeLog.warn("backdrop: unsupported filter \"\(t)\" in \"\(raw)\"")
            return fallback
        }
        return AlmadarTheme.Backdrop(blurRadius: blur, saturation: saturation)
    }

    static func cssImage(_ raw: String?, fallback: AlmadarTheme.SurfaceImage) -> AlmadarTheme.SurfaceImage {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("cssImage: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        if raw == "none" { return .noImage }
        let functions: [String] = ["linear-gradient(", "radial-gradient(", "conic-gradient(", "repeating-linear-gradient(", "repeating-radial-gradient(", "repeating-conic-gradient(", "url("]
        if functions.contains(where: { raw.hasPrefix($0) }) { return .css(raw) }
        AlmadarThemeLog.warn("cssImage: unparseable value \"\(raw)\"")
        return fallback
    }

    static func tileSizes(_ raw: String?, fallback: [AlmadarTheme.TileSize]) -> [AlmadarTheme.TileSize] {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("tileSizes: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        var out: [AlmadarTheme.TileSize] = []
        for layer in splitTopLevel(raw, separator: ",") {
            let parts = splitTopLevel(layer, separator: " ")
            guard parts.count == 1 || parts.count == 2 else {
                AlmadarThemeLog.warn("tileSizes: unparseable value \"\(raw)\"")
                return fallback
            }
            var dims: [CGFloat?] = []
            for p in parts {
                if p == "auto" { dims.append(nil) } else if let n = lengthValue(p) { dims.append(n) } else {
                    AlmadarThemeLog.warn("tileSizes: unparseable value \"\(raw)\"")
                    return fallback
                }
            }
            out.append(AlmadarTheme.TileSize(width: dims[0], height: dims.count == 2 ? dims[1] : nil))
        }
        return out
    }

    static func responsiveLength(_ raw: String?, fallback: AlmadarTheme.ResponsiveLength) -> AlmadarTheme.ResponsiveLength {
        guard let raw = raw, !raw.isEmpty else { return fallback }
        if isUnresolvedVarRef(raw) {
            AlmadarThemeLog.warn("responsiveLength: unresolved CSS var reference \"\(raw)\"")
            return fallback
        }
        if raw.hasPrefix("clamp("), raw.hasSuffix(")") {
            let args = splitTopLevel(String(raw.dropFirst(6).dropLast()), separator: ",")
            if args.count == 3, let lo = lengthValue(args[0]), let hi = lengthValue(args[2]) {
                if args[1].hasSuffix("vw"), let vw = Double(args[1].dropLast(2)) {
                    return AlmadarTheme.ResponsiveLength(lower: lo, preferredVw: vw, fixed: 0, upper: hi)
                }
                if let fx = lengthValue(args[1]) {
                    return AlmadarTheme.ResponsiveLength(lower: lo, preferredVw: 0, fixed: fx, upper: hi)
                }
            }
        } else if let v = lengthValue(raw) {
            return AlmadarTheme.ResponsiveLength(lower: v, preferredVw: 0, fixed: v, upper: v)
        }
        AlmadarThemeLog.warn("responsiveLength: unparseable value \"\(raw)\"")
        return fallback
    }

    /// Returns nil for a generic CSS keyword or an unresolved `var(...)`
    /// reference — both mean "use the platform system font", not an error.
    static func fontFamilyName(_ raw: String?) -> String? {
        guard let raw = raw, !raw.isEmpty else { return nil }
        let first = raw.split(separator: ",").first.map { $0.trimmingCharacters(in: CharacterSet(charactersIn: " '\"")) } ?? raw
        let generic: Set<String> = ["sans-serif", "serif", "monospace", "ui-monospace", "ui-sans-serif", "ui-serif", "system-ui", "-apple-system"]
        if first.isEmpty || isUnresolvedVarRef(first) || generic.contains(first) { return nil }
        return first
    }

    private static let sizeRelativeStyle: [String: UIFont.TextStyle] = [
        "xs": .caption2,
        "sm": .caption1,
        "base": .body,
        "lg": .title3,
        "xl": .title2,
        "2xl": .title1,
        "3xl": .largeTitle,
        "4xl": .largeTitle,
        "display-1": .largeTitle,
        "display-2": .largeTitle,
    ]

    /// A raw point size + weight, scaled against the OS Dynamic Type category
    /// the size key coarsely maps to (`UIFontMetrics`), so the app respects
    /// the user's text-size setting even though the theme names an exact px
    /// value — the system-font path when `family` is nil (no named font).
    static func scaledFont(family: String?, sizeKey: String, size: CGFloat, weight: Font.Weight) -> Font {
        let relativeStyle = sizeRelativeStyle[sizeKey] ?? .body
        if let family = family {
            let swiftStyle: Font.TextStyle = swiftRelativeStyle(relativeStyle)
            return Font.custom(family, size: size, relativeTo: swiftStyle).weight(weight)
        }
        let uiWeight: UIFont.Weight
        switch weight {
        case .bold: uiWeight = .bold
        case .medium: uiWeight = .medium
        default: uiWeight = .regular
        }
        let base = UIFont.systemFont(ofSize: size, weight: uiWeight)
        let scaled = UIFontMetrics(forTextStyle: relativeStyle).scaledFont(for: base)
        return Font(scaled)
    }

    private static func swiftRelativeStyle(_ style: UIFont.TextStyle) -> Font.TextStyle {
        switch style {
        case .caption2: return .caption2
        case .caption1: return .caption
        case .title3: return .title3
        case .title2: return .title2
        case .title1: return .title
        case .largeTitle: return .largeTitle
        default: return .body
        }
    }
}

// MARK: - AlmadarTheme — the resolved, typed value the app renders through

struct AlmadarTheme {
    enum CornerShape: Equatable {
        case round, squircle, bevel, scoop, notch
        case superellipse(Double)
    }

    enum BorderLineStyle: String {
        case none, hidden, dotted, dashed, solid, double, groove, ridge, inset, outset
    }

    enum TextTransform: String {
        case none, uppercase, lowercase, capitalize
    }

    enum FontSlant: String {
        case normal, italic, oblique
    }

    /// CSS letter-spacing: `value` in em when `isEm`, else points.
    struct Tracking: Equatable {
        let value: Double
        let isEm: Bool
    }

    /// CSS backdrop-filter `blur(...) saturate(...)`: gaussian radius + saturation multiplier.
    struct Backdrop: Equatable {
        let blurRadius: CGFloat
        let saturation: Double
    }

    /// A CSS `<image>` layer list kept as its declared string — gradients, tiles and
    /// SVG data-URI masks have no native value to parse into, so a renderer interprets the CSS.
    enum SurfaceImage: Equatable {
        case noImage
        case css(String)
    }

    /// One layer of a CSS `background-size` / `mask-size` list; nil = `auto`.
    struct TileSize: Equatable {
        let width: CGFloat?
        let height: CGFloat?
    }

    /// `clamp(lower, fixed + preferredVw vw, upper)`; a plain length has lower == fixed == upper.
    struct ResponsiveLength: Equatable {
        let lower: CGFloat
        let preferredVw: Double
        let fixed: CGFloat
        let upper: CGFloat

        func resolve(viewportWidth: CGFloat) -> CGFloat {
            let preferred = fixed + CGFloat(preferredVw / 100) * viewportWidth
            return min(max(preferred, lower), upper)
        }
    }

    struct ColorPalette {
        let primary: Color
        let primaryHover: Color
        let primaryForeground: Color
        let secondary: Color
        let secondaryHover: Color
        let secondaryForeground: Color
        let accent: Color
        let accentForeground: Color
        let muted: Color
        let mutedForeground: Color
        let background: Color
        let foreground: Color
        let card: Color
        let cardForeground: Color
        let surface: Color
        let border: Color
        let input: Color
        let ring: Color
        let error: Color
        let errorForeground: Color
        let success: Color
        let successForeground: Color
        let warning: Color
        let warningForeground: Color
        let info: Color
        let infoForeground: Color
        let tableHeader: Color
        let tableBorder: Color
        let tableRowHover: Color
        let surfaceHover: Color
        let borderHover: Color
        let placeholder: Color
        let scrim: Color
    }

    struct DensityScale {
        struct Spacing {
            let space0: CGFloat
            let space1: CGFloat
            let space2: CGFloat
            let space3: CGFloat
            let space4: CGFloat
            let space5: CGFloat
            let space6: CGFloat
            let space7: CGFloat
            let space8: CGFloat
            let space9: CGFloat
            let space10: CGFloat
            let space11: CGFloat
            let space12: CGFloat
        }
        let spacing: Spacing
        let buttonHeightSm: CGFloat
        let buttonHeightMd: CGFloat
        let buttonHeightLg: CGFloat
        let inputHeightSm: CGFloat
        let inputHeightMd: CGFloat
        let inputHeightLg: CGFloat
        let rowHeightCompact: CGFloat
        let rowHeightNormal: CGFloat
        let rowHeightSpacious: CGFloat
        let cardPaddingSm: CGFloat
        let cardPaddingMd: CGFloat
        let cardPaddingLg: CGFloat
        let dialogPadding: CGFloat
        let sectionGap: CGFloat
    }

    struct TypeScale {
        struct Entry { let size: CGFloat; let lineHeight: CGFloat }
        struct Intent { let font: Font; let lineHeight: CGFloat }
        let displayFamily: String?
        let bodyFamily: String?
        let monoFamily: String?
        struct Heading {
            let weight: Font.Weight
            let transform: AlmadarTheme.TextTransform
            let tracking: AlmadarTheme.Tracking
            let style: AlmadarTheme.FontSlant
            let shadow: AlmadarTheme.ElevationScale.Shadow?
        }
        let heading: Heading
        struct Scale {
            let xs: Entry
            let sm: Entry
            let base: Entry
            let lg: Entry
            let xl: Entry
            let xl2: Entry
            let xl3: Entry
            let xl4: Entry
            let display1: Entry
            let display2: Entry
        }
        let scale: Scale
        let headingMajor: Intent
        let headingMinor: Intent
        let bodyEmphasis: Intent
        let bodyDefault: Intent
        let bodyQuiet: Intent
        let caption: Intent
        let numeric: Intent
    }

    struct MotionScale {
        struct Curve { let x1: Double; let y1: Double; let x2: Double; let y2: Double }
        struct Intent { let duration: Double; let easing: Curve }
        struct Durations {
            let instant: Double
            let fast: Double
            let normal: Double
            let slow: Double
            let dramatic: Double
        }
        struct Easings {
            let linear: Curve
            let standard: Curve
            let emphasized: Curve
            let spring: Curve
        }
        let durations: Durations
        let easings: Easings
        let enter: Intent
        let exit: Intent
        let hover: Intent
        let press: Intent
        let expand: Intent
        let transition: Intent
        /// `--motion-busy-delay`: how long a round trip runs before busy affordances show (seconds).
        let busyDelay: Double
        /// `--awaiting-skeleton-display`: whether an empty slot shows the predicted skeleton.
        let awaitingSkeleton: Bool

        /// `duration`/`easing` in seconds/curve for the given intent — the
        /// only shape `SwiftUI.Animation` needs.
        func animation(for intent: Intent) -> Animation {
            .timingCurve(intent.easing.x1, intent.easing.y1, intent.easing.x2, intent.easing.y2, duration: intent.duration)
        }
    }

    struct IconographyScale {
        let family: String
        let strokeWidth: Double
        let defaultSize: CGFloat
    }

    struct ElevationScale {
        struct Shadow {
            var color: Color
            var radius: CGFloat
            var x: CGFloat
            var y: CGFloat
            var spread: CGFloat = 0
            var inset: Bool = false
            var underlays: [Shadow] = []
        }
        let cardElevation: Shadow
        let popoverElevation: Shadow
        let dialogElevation: Shadow
        let toastElevation: Shadow
        let interactiveElevation: Shadow
        let pressedElevation: Shadow
    }

    struct GeometryScale {
        let radiusContainer: CGFloat
        let radiusInteractive: CGFloat
        let radiusPill: CGFloat
        let borderHairline: CGFloat
        let borderStandard: CGFloat
        let borderHeavy: CGFloat
        let cornerShape: AlmadarTheme.CornerShape
        let cornerShapePill: AlmadarTheme.CornerShape
        let cornerShapeInteractive: AlmadarTheme.CornerShape
        let borderStyle: AlmadarTheme.BorderLineStyle
        let borderStyleInteractive: AlmadarTheme.BorderLineStyle
    }

    struct SurfaceScale {
        let backdrop: AlmadarTheme.Backdrop?
        let cardImage: AlmadarTheme.SurfaceImage
        let pageImage: AlmadarTheme.SurfaceImage
        let pageImageSize: [AlmadarTheme.TileSize]
        let diagram: Color
        let edgeMask: AlmadarTheme.SurfaceImage
        let edgeHeight: AlmadarTheme.ResponsiveLength
        let textureMask: AlmadarTheme.SurfaceImage
        let textureSize: [AlmadarTheme.TileSize]
        let accentImage: AlmadarTheme.SurfaceImage
        let scrim: AlmadarTheme.SurfaceImage
    }

    let color: ColorPalette
    let density: DensityScale
    let typeScale: TypeScale
    let motion: MotionScale
    let iconography: IconographyScale
    let elevation: ElevationScale
    let geometry: GeometryScale
    let surface: SurfaceScale

    /// `minimalist` preset's base (light) tokens, baked at generation time
    /// (`packages/almadar-core/themes/minimalist.json` via `THEME_PRESETS`)
    /// — always available before the kernel snapshot supplies a live theme
    /// (set by the kernel snapshot (wave B7)).
    static let fallback: AlmadarTheme = AlmadarTheme.from(tokens: ThemeTokensJSON.fallback, mode: .light, fallbackChain: nil)

    /// `tokens` is assumed already resolved for `mode` (dark-variant merge
    /// happens upstream, `orbital-core::runtime::theme::resolve` — wave
    /// C1(c)); `mode` is carried for callers that need it, not used to
    /// re-merge here. `fallbackChain` supplies the "unparseable" fallback
    /// for every leaf — omit (nil) only when bootstrapping `.fallback`
    /// itself, which is then its own fallback chain (self-referential base
    /// case, guarded by using literal zero-ish defaults for that one call).
    static func from(tokens: ThemeTokensJSON, mode: ColorScheme, fallbackChain: AlmadarTheme?) -> AlmadarTheme {
        let fb = fallbackChain ?? AlmadarTheme.bootstrapDefaults

        let colorAxis = tokens.color
        let legacyColors = tokens.colors ?? [:]
        let color = ColorPalette(
            primary: AlmadarThemeParse.color(colorAxis?.primary ?? legacyColors["primary"], fallback: fb.color.primary),
            primaryHover: AlmadarThemeParse.color(colorAxis?.primaryHover ?? legacyColors["primary-hover"], fallback: fb.color.primaryHover),
            primaryForeground: AlmadarThemeParse.color(colorAxis?.primaryForeground ?? legacyColors["primary-foreground"], fallback: fb.color.primaryForeground),
            secondary: AlmadarThemeParse.color(colorAxis?.secondary ?? legacyColors["secondary"], fallback: fb.color.secondary),
            secondaryHover: AlmadarThemeParse.color(colorAxis?.secondaryHover ?? legacyColors["secondary-hover"], fallback: fb.color.secondaryHover),
            secondaryForeground: AlmadarThemeParse.color(colorAxis?.secondaryForeground ?? legacyColors["secondary-foreground"], fallback: fb.color.secondaryForeground),
            accent: AlmadarThemeParse.color(colorAxis?.accent ?? legacyColors["accent"], fallback: fb.color.accent),
            accentForeground: AlmadarThemeParse.color(colorAxis?.accentForeground ?? legacyColors["accent-foreground"], fallback: fb.color.accentForeground),
            muted: AlmadarThemeParse.color(colorAxis?.muted ?? legacyColors["muted"], fallback: fb.color.muted),
            mutedForeground: AlmadarThemeParse.color(colorAxis?.mutedForeground ?? legacyColors["muted-foreground"], fallback: fb.color.mutedForeground),
            background: AlmadarThemeParse.color(colorAxis?.background ?? legacyColors["background"], fallback: fb.color.background),
            foreground: AlmadarThemeParse.color(colorAxis?.foreground ?? legacyColors["foreground"], fallback: fb.color.foreground),
            card: AlmadarThemeParse.color(colorAxis?.card ?? legacyColors["card"], fallback: fb.color.card),
            cardForeground: AlmadarThemeParse.color(colorAxis?.cardForeground ?? legacyColors["card-foreground"], fallback: fb.color.cardForeground),
            surface: AlmadarThemeParse.color(colorAxis?.surface ?? legacyColors["surface"], fallback: fb.color.surface),
            border: AlmadarThemeParse.color(colorAxis?.border ?? legacyColors["border"], fallback: fb.color.border),
            input: AlmadarThemeParse.color(colorAxis?.input ?? legacyColors["input"], fallback: fb.color.input),
            ring: AlmadarThemeParse.color(colorAxis?.ring ?? legacyColors["ring"], fallback: fb.color.ring),
            error: AlmadarThemeParse.color(colorAxis?.error ?? legacyColors["error"], fallback: fb.color.error),
            errorForeground: AlmadarThemeParse.color(colorAxis?.errorForeground ?? legacyColors["error-foreground"], fallback: fb.color.errorForeground),
            success: AlmadarThemeParse.color(colorAxis?.success ?? legacyColors["success"], fallback: fb.color.success),
            successForeground: AlmadarThemeParse.color(colorAxis?.successForeground ?? legacyColors["success-foreground"], fallback: fb.color.successForeground),
            warning: AlmadarThemeParse.color(colorAxis?.warning ?? legacyColors["warning"], fallback: fb.color.warning),
            warningForeground: AlmadarThemeParse.color(colorAxis?.warningForeground ?? legacyColors["warning-foreground"], fallback: fb.color.warningForeground),
            info: AlmadarThemeParse.color(colorAxis?.info ?? legacyColors["info"], fallback: fb.color.info),
            infoForeground: AlmadarThemeParse.color(colorAxis?.infoForeground ?? legacyColors["info-foreground"], fallback: fb.color.infoForeground),
            tableHeader: AlmadarThemeParse.color(colorAxis?.tableHeader ?? legacyColors["table-header"], fallback: fb.color.tableHeader),
            tableBorder: AlmadarThemeParse.color(colorAxis?.tableBorder ?? legacyColors["table-border"], fallback: fb.color.tableBorder),
            tableRowHover: AlmadarThemeParse.color(colorAxis?.tableRowHover ?? legacyColors["table-row-hover"], fallback: fb.color.tableRowHover),
            surfaceHover: AlmadarThemeParse.color(colorAxis?.surfaceHover ?? legacyColors["surface-hover"], fallback: fb.color.surfaceHover),
            borderHover: AlmadarThemeParse.color(colorAxis?.borderHover ?? legacyColors["border-hover"], fallback: fb.color.borderHover),
            placeholder: AlmadarThemeParse.color(colorAxis?.placeholder ?? legacyColors["placeholder"], fallback: fb.color.placeholder),
            scrim: AlmadarThemeParse.color(colorAxis?.scrim ?? legacyColors["scrim"], fallback: fb.color.scrim),
        )

        let densityAxis = tokens.density
        let spacing = DensityScale.Spacing(
            space0: AlmadarThemeParse.length(densityAxis?.spacing?.space0, fallback: fb.density.spacing.space0),
            space1: AlmadarThemeParse.length(densityAxis?.spacing?.space1, fallback: fb.density.spacing.space1),
            space2: AlmadarThemeParse.length(densityAxis?.spacing?.space2, fallback: fb.density.spacing.space2),
            space3: AlmadarThemeParse.length(densityAxis?.spacing?.space3, fallback: fb.density.spacing.space3),
            space4: AlmadarThemeParse.length(densityAxis?.spacing?.space4, fallback: fb.density.spacing.space4),
            space5: AlmadarThemeParse.length(densityAxis?.spacing?.space5, fallback: fb.density.spacing.space5),
            space6: AlmadarThemeParse.length(densityAxis?.spacing?.space6, fallback: fb.density.spacing.space6),
            space7: AlmadarThemeParse.length(densityAxis?.spacing?.space7, fallback: fb.density.spacing.space7),
            space8: AlmadarThemeParse.length(densityAxis?.spacing?.space8, fallback: fb.density.spacing.space8),
            space9: AlmadarThemeParse.length(densityAxis?.spacing?.space9, fallback: fb.density.spacing.space9),
            space10: AlmadarThemeParse.length(densityAxis?.spacing?.space10, fallback: fb.density.spacing.space10),
            space11: AlmadarThemeParse.length(densityAxis?.spacing?.space11, fallback: fb.density.spacing.space11),
            space12: AlmadarThemeParse.length(densityAxis?.spacing?.space12, fallback: fb.density.spacing.space12),
        )
        let density = DensityScale(
            spacing: spacing,
            buttonHeightSm: AlmadarThemeParse.length(densityAxis?.buttonHeightSm, fallback: fb.density.buttonHeightSm),
            buttonHeightMd: AlmadarThemeParse.length(densityAxis?.buttonHeightMd, fallback: fb.density.buttonHeightMd),
            buttonHeightLg: AlmadarThemeParse.length(densityAxis?.buttonHeightLg, fallback: fb.density.buttonHeightLg),
            inputHeightSm: AlmadarThemeParse.length(densityAxis?.inputHeightSm, fallback: fb.density.inputHeightSm),
            inputHeightMd: AlmadarThemeParse.length(densityAxis?.inputHeightMd, fallback: fb.density.inputHeightMd),
            inputHeightLg: AlmadarThemeParse.length(densityAxis?.inputHeightLg, fallback: fb.density.inputHeightLg),
            rowHeightCompact: AlmadarThemeParse.length(densityAxis?.rowHeightCompact, fallback: fb.density.rowHeightCompact),
            rowHeightNormal: AlmadarThemeParse.length(densityAxis?.rowHeightNormal, fallback: fb.density.rowHeightNormal),
            rowHeightSpacious: AlmadarThemeParse.length(densityAxis?.rowHeightSpacious, fallback: fb.density.rowHeightSpacious),
            cardPaddingSm: AlmadarThemeParse.length(densityAxis?.cardPaddingSm, fallback: fb.density.cardPaddingSm),
            cardPaddingMd: AlmadarThemeParse.length(densityAxis?.cardPaddingMd, fallback: fb.density.cardPaddingMd),
            cardPaddingLg: AlmadarThemeParse.length(densityAxis?.cardPaddingLg, fallback: fb.density.cardPaddingLg),
            dialogPadding: AlmadarThemeParse.length(densityAxis?.dialogPadding, fallback: fb.density.dialogPadding),
            sectionGap: AlmadarThemeParse.length(densityAxis?.sectionGap, fallback: fb.density.sectionGap),
        )

        let typeAxis = tokens.typeScale
        func scaleEntry(_ jsonKey: String, _ e: ThemeTokensJSON.TypeScaleEntry?, _ fb: TypeScale.Entry) -> TypeScale.Entry {
            TypeScale.Entry(
                size: AlmadarThemeParse.length(e?.size, fallback: fb.size),
                lineHeight: AlmadarThemeParse.length(e?.lineHeight, fallback: fb.lineHeight)
            )
        }
        let scale = TypeScale.Scale(
            xs: scaleEntry("xs", typeAxis?.scale?.xs, fb.typeScale.scale.xs),
            sm: scaleEntry("sm", typeAxis?.scale?.sm, fb.typeScale.scale.sm),
            base: scaleEntry("base", typeAxis?.scale?.base, fb.typeScale.scale.base),
            lg: scaleEntry("lg", typeAxis?.scale?.lg, fb.typeScale.scale.lg),
            xl: scaleEntry("xl", typeAxis?.scale?.xl, fb.typeScale.scale.xl),
            xl2: scaleEntry("2xl", typeAxis?.scale?.xl2, fb.typeScale.scale.xl2),
            xl3: scaleEntry("3xl", typeAxis?.scale?.xl3, fb.typeScale.scale.xl3),
            xl4: scaleEntry("4xl", typeAxis?.scale?.xl4, fb.typeScale.scale.xl4),
            display1: scaleEntry("display-1", typeAxis?.scale?.display1, fb.typeScale.scale.display1),
            display2: scaleEntry("display-2", typeAxis?.scale?.display2, fb.typeScale.scale.display2),
        )
        func resolvedIntentFont(sizeKey: ThemeTokensJSON.TypeIntent?, fallbackSizeKey: String) -> (Font, CGFloat) {
            let key = sizeKey?.size ?? fallbackSizeKey
            let weightRaw = sizeKey?.weight
            let weight: Font.Weight = weightRaw == "bold" ? .bold : (weightRaw == "medium" ? .medium : .regular)
            let entry: TypeScale.Entry
            switch key {
            case "xs": entry = scale.xs
            case "sm": entry = scale.sm
            case "base": entry = scale.base
            case "lg": entry = scale.lg
            case "xl": entry = scale.xl
            case "2xl": entry = scale.xl2
            case "3xl": entry = scale.xl3
            case "4xl": entry = scale.xl4
            case "display-1": entry = scale.display1
            case "display-2": entry = scale.display2
            default: entry = scale.base
            }
            let familyRaw: String?
            switch sizeKey?.slot {
            case "display": familyRaw = typeAxis?.displayFamily ?? typeAxis?.bodyFamily
            case "mono": familyRaw = typeAxis?.monoFamily ?? typeAxis?.bodyFamily
            default: familyRaw = typeAxis?.bodyFamily ?? typeAxis?.displayFamily
            }
            let family = AlmadarThemeParse.fontFamilyName(familyRaw)
            let font = AlmadarThemeParse.scaledFont(family: family, sizeKey: key, size: entry.size, weight: weight)
            return (font, entry.lineHeight)
        }
        let heading = TypeScale.Heading(
            weight: AlmadarThemeParse.fontWeight(typeAxis?.headingWeight, fallback: fb.typeScale.heading.weight),
            transform: AlmadarThemeParse.textTransform(typeAxis?.headingTransform, fallback: fb.typeScale.heading.transform),
            tracking: AlmadarThemeParse.tracking(typeAxis?.headingTracking, fallback: fb.typeScale.heading.tracking),
            style: AlmadarThemeParse.fontSlant(typeAxis?.headingStyle, fallback: fb.typeScale.heading.style),
            shadow: AlmadarThemeParse.textShadow(typeAxis?.headingShadow, fallback: fb.typeScale.heading.shadow),
        )
        let typeScale = TypeScale(
            displayFamily: AlmadarThemeParse.fontFamilyName(typeAxis?.displayFamily) ?? typeAxis?.displayFamily,
            bodyFamily: AlmadarThemeParse.fontFamilyName(typeAxis?.bodyFamily) ?? typeAxis?.bodyFamily,
            monoFamily: AlmadarThemeParse.fontFamilyName(typeAxis?.monoFamily) ?? typeAxis?.monoFamily,
            heading: heading,
            scale: scale,
            headingMajor: { let (f, lh) = resolvedIntentFont(sizeKey: typeAxis?.intents?.headingMajor, fallbackSizeKey: "base"); return TypeScale.Intent(font: f, lineHeight: lh) }(),
            headingMinor: { let (f, lh) = resolvedIntentFont(sizeKey: typeAxis?.intents?.headingMinor, fallbackSizeKey: "base"); return TypeScale.Intent(font: f, lineHeight: lh) }(),
            bodyEmphasis: { let (f, lh) = resolvedIntentFont(sizeKey: typeAxis?.intents?.bodyEmphasis, fallbackSizeKey: "base"); return TypeScale.Intent(font: f, lineHeight: lh) }(),
            bodyDefault: { let (f, lh) = resolvedIntentFont(sizeKey: typeAxis?.intents?.bodyDefault, fallbackSizeKey: "base"); return TypeScale.Intent(font: f, lineHeight: lh) }(),
            bodyQuiet: { let (f, lh) = resolvedIntentFont(sizeKey: typeAxis?.intents?.bodyQuiet, fallbackSizeKey: "base"); return TypeScale.Intent(font: f, lineHeight: lh) }(),
            caption: { let (f, lh) = resolvedIntentFont(sizeKey: typeAxis?.intents?.caption, fallbackSizeKey: "base"); return TypeScale.Intent(font: f, lineHeight: lh) }(),
            numeric: { let (f, lh) = resolvedIntentFont(sizeKey: typeAxis?.intents?.numeric, fallbackSizeKey: "base"); return TypeScale.Intent(font: f, lineHeight: lh) }(),
        )

        let motionAxis = tokens.motion
        let durations = MotionScale.Durations(
            instant: AlmadarThemeParse.duration(motionAxis?.durations?.instant, fallback: fb.motion.durations.instant),
            fast: AlmadarThemeParse.duration(motionAxis?.durations?.fast, fallback: fb.motion.durations.fast),
            normal: AlmadarThemeParse.duration(motionAxis?.durations?.normal, fallback: fb.motion.durations.normal),
            slow: AlmadarThemeParse.duration(motionAxis?.durations?.slow, fallback: fb.motion.durations.slow),
            dramatic: AlmadarThemeParse.duration(motionAxis?.durations?.dramatic, fallback: fb.motion.durations.dramatic),
        )
        let easings = MotionScale.Easings(
            linear: AlmadarThemeParse.easing(motionAxis?.easings?.linear, fallback: fb.motion.easings.linear),
            standard: AlmadarThemeParse.easing(motionAxis?.easings?.standard, fallback: fb.motion.easings.standard),
            emphasized: AlmadarThemeParse.easing(motionAxis?.easings?.emphasized, fallback: fb.motion.easings.emphasized),
            spring: AlmadarThemeParse.easing(motionAxis?.easings?.spring, fallback: fb.motion.easings.spring),
        )
        func resolvedMotionIntent(_ i: ThemeTokensJSON.MotionIntent?, _ fb: MotionScale.Intent) -> MotionScale.Intent {
            let durationKey = i?.duration
            let easingKey = i?.easing
            let duration: Double
            switch durationKey {
            case "instant": duration = durations.instant
            case "fast": duration = durations.fast
            case "normal": duration = durations.normal
            case "slow": duration = durations.slow
            case "dramatic": duration = durations.dramatic
            default: duration = fb.duration
            }
            let easing: MotionScale.Curve
            switch easingKey {
            case "linear": easing = easings.linear
            case "standard": easing = easings.standard
            case "emphasized": easing = easings.emphasized
            case "spring": easing = easings.spring
            default: easing = fb.easing
            }
            return MotionScale.Intent(duration: duration, easing: easing)
        }
        let motion = MotionScale(
            durations: durations,
            easings: easings,
            enter: resolvedMotionIntent(motionAxis?.intents?.enter, fb.motion.enter),
            exit: resolvedMotionIntent(motionAxis?.intents?.exit, fb.motion.exit),
            hover: resolvedMotionIntent(motionAxis?.intents?.hover, fb.motion.hover),
            press: resolvedMotionIntent(motionAxis?.intents?.press, fb.motion.press),
            expand: resolvedMotionIntent(motionAxis?.intents?.expand, fb.motion.expand),
            transition: resolvedMotionIntent(motionAxis?.intents?.transition, fb.motion.transition),
            busyDelay: AlmadarThemeParse.duration(motionAxis?.busyDelay, fallback: fb.motion.busyDelay),
            awaitingSkeleton: motionAxis?.awaitingSkeleton ?? fb.motion.awaitingSkeleton
        )

        let iconAxis = tokens.iconography
        let iconography = IconographyScale(
            family: iconAxis?.family ?? fb.iconography.family,
            strokeWidth: AlmadarThemeParse.number(iconAxis?.strokeWidth, fallback: fb.iconography.strokeWidth),
            defaultSize: AlmadarThemeParse.length(iconAxis?.defaultSize, fallback: fb.iconography.defaultSize)
        )

        let elevationAxis = tokens.elevation
        let elevation = ElevationScale(
            cardElevation: AlmadarThemeParse.shadow(AlmadarThemeParse.resolveShadowRef(elevationAxis?.cardElevation, tokens.shadows), fallback: fb.elevation.cardElevation),
            popoverElevation: AlmadarThemeParse.shadow(AlmadarThemeParse.resolveShadowRef(elevationAxis?.popoverElevation, tokens.shadows), fallback: fb.elevation.popoverElevation),
            dialogElevation: AlmadarThemeParse.shadow(AlmadarThemeParse.resolveShadowRef(elevationAxis?.dialogElevation, tokens.shadows), fallback: fb.elevation.dialogElevation),
            toastElevation: AlmadarThemeParse.shadow(AlmadarThemeParse.resolveShadowRef(elevationAxis?.toastElevation, tokens.shadows), fallback: fb.elevation.toastElevation),
            interactiveElevation: AlmadarThemeParse.shadow(AlmadarThemeParse.resolveShadowRef(elevationAxis?.interactiveElevation, tokens.shadows), fallback: fb.elevation.interactiveElevation),
            pressedElevation: AlmadarThemeParse.shadow(AlmadarThemeParse.resolveShadowRef(elevationAxis?.pressedElevation, tokens.shadows), fallback: fb.elevation.pressedElevation),
        )

        let geometryAxis = tokens.geometry
        let geometry = GeometryScale(
            radiusContainer: AlmadarThemeParse.length(AlmadarThemeParse.resolveRadiusRef(geometryAxis?.radiusContainer, tokens.radii), fallback: fb.geometry.radiusContainer),
            radiusInteractive: AlmadarThemeParse.length(AlmadarThemeParse.resolveRadiusRef(geometryAxis?.radiusInteractive, tokens.radii), fallback: fb.geometry.radiusInteractive),
            radiusPill: AlmadarThemeParse.length(AlmadarThemeParse.resolveRadiusRef(geometryAxis?.radiusPill, tokens.radii), fallback: fb.geometry.radiusPill),
            borderHairline: AlmadarThemeParse.length(AlmadarThemeParse.resolveRadiusRef(geometryAxis?.borderHairline, tokens.radii), fallback: fb.geometry.borderHairline),
            borderStandard: AlmadarThemeParse.length(AlmadarThemeParse.resolveRadiusRef(geometryAxis?.borderStandard, tokens.radii), fallback: fb.geometry.borderStandard),
            borderHeavy: AlmadarThemeParse.length(AlmadarThemeParse.resolveRadiusRef(geometryAxis?.borderHeavy, tokens.radii), fallback: fb.geometry.borderHeavy),
            cornerShape: AlmadarThemeParse.cornerShape(geometryAxis?.cornerShape, fallback: fb.geometry.cornerShape),
            cornerShapePill: AlmadarThemeParse.cornerShape(geometryAxis?.cornerShapePill, fallback: fb.geometry.cornerShapePill),
            cornerShapeInteractive: AlmadarThemeParse.cornerShape(geometryAxis?.cornerShapeInteractive, fallback: fb.geometry.cornerShapeInteractive),
            borderStyle: AlmadarThemeParse.borderStyle(geometryAxis?.borderStyle, fallback: fb.geometry.borderStyle),
            borderStyleInteractive: AlmadarThemeParse.borderStyle(geometryAxis?.borderStyleInteractive, fallback: fb.geometry.borderStyleInteractive),
        )

        let surfaceAxis = tokens.surface
        let surface = SurfaceScale(
            backdrop: AlmadarThemeParse.backdrop(surfaceAxis?.backdrop, fallback: fb.surface.backdrop),
            cardImage: AlmadarThemeParse.cssImage(surfaceAxis?.cardImage, fallback: fb.surface.cardImage),
            pageImage: AlmadarThemeParse.cssImage(surfaceAxis?.pageImage, fallback: fb.surface.pageImage),
            pageImageSize: AlmadarThemeParse.tileSizes(surfaceAxis?.pageImageSize, fallback: fb.surface.pageImageSize),
            diagram: AlmadarThemeParse.color(surfaceAxis?.diagram, fallback: fb.surface.diagram),
            edgeMask: AlmadarThemeParse.cssImage(surfaceAxis?.edgeMask, fallback: fb.surface.edgeMask),
            edgeHeight: AlmadarThemeParse.responsiveLength(surfaceAxis?.edgeHeight, fallback: fb.surface.edgeHeight),
            textureMask: AlmadarThemeParse.cssImage(surfaceAxis?.textureMask, fallback: fb.surface.textureMask),
            textureSize: AlmadarThemeParse.tileSizes(surfaceAxis?.textureSize, fallback: fb.surface.textureSize),
            accentImage: AlmadarThemeParse.cssImage(surfaceAxis?.accentImage, fallback: fb.surface.accentImage),
            scrim: AlmadarThemeParse.cssImage(surfaceAxis?.scrim, fallback: fb.surface.scrim),
        )

        return AlmadarTheme(color: color, density: density, typeScale: typeScale, motion: motion, iconography: iconography, elevation: elevation, geometry: geometry, surface: surface)
    }

    /// Zero-ish literal defaults used ONLY while resolving `.fallback` itself
    /// (there is no earlier fallback to chain to) — every field a literal,
    /// never derived from a parse.
    private static let bootstrapDefaults: AlmadarTheme = {
        let zeroColor = Color(.sRGB, red: 0, green: 0, blue: 0, opacity: 1)
