            density: DensityScale(
                spacing: DensityScale.Spacing(space0: 4, space1: 4, space2: 4, space3: 4, space4: 4, space5: 4, space6: 4, space7: 4, space8: 4, space9: 4, space10: 4, space11: 4, space12: 4),
                buttonHeightSm: 40, buttonHeightMd: 40, buttonHeightLg: 40, inputHeightSm: 40, inputHeightMd: 40, inputHeightLg: 40, rowHeightCompact: 40, rowHeightNormal: 40, rowHeightSpacious: 40, cardPaddingSm: 40, cardPaddingMd: 40, cardPaddingLg: 40, dialogPadding: 40, sectionGap: 40
            ),
            typeScale: TypeScale(
                displayFamily: nil, bodyFamily: nil, monoFamily: nil,
                heading: TypeScale.Heading(weight: .regular, transform: .none, tracking: .init(value: 0, isEm: true), style: .normal, shadow: nil),
                scale: TypeScale.Scale(xs: zeroEntry, sm: zeroEntry, base: zeroEntry, lg: zeroEntry, xl: zeroEntry, xl2: zeroEntry, xl3: zeroEntry, xl4: zeroEntry, display1: zeroEntry, display2: zeroEntry),
                headingMajor: zeroIntent, headingMinor: zeroIntent, bodyEmphasis: zeroIntent, bodyDefault: zeroIntent, bodyQuiet: zeroIntent, caption: zeroIntent, numeric: zeroIntent
            ),
            motion: MotionScale(
                durations: MotionScale.Durations(instant: 0.2, fast: 0.2, normal: 0.2, slow: 0.2, dramatic: 0.2),
                easings: MotionScale.Easings(linear: zeroCurve, standard: zeroCurve, emphasized: zeroCurve, spring: zeroCurve),
                enter: zeroMotionIntent, exit: zeroMotionIntent, hover: zeroMotionIntent, press: zeroMotionIntent, expand: zeroMotionIntent, transition: zeroMotionIntent,
                busyDelay: 0.3, awaitingSkeleton: false
            ),
            iconography: IconographyScale(family: "lucide", strokeWidth: 1.5, defaultSize: 16),
            elevation: ElevationScale(cardElevation: zeroShadow, popoverElevation: zeroShadow, dialogElevation: zeroShadow, toastElevation: zeroShadow, interactiveElevation: zeroShadow, pressedElevation: zeroShadow),
            geometry: GeometryScale(radiusContainer: 4, radiusInteractive: 4, radiusPill: 4, borderHairline: 4, borderStandard: 4, borderHeavy: 4, cornerShape: .round, cornerShapePill: .round, cornerShapeInteractive: .round, borderStyle: .solid, borderStyleInteractive: .solid),
            surface: SurfaceScale(backdrop: nil, cardImage: .noImage, pageImage: .noImage, pageImageSize: [], diagram: zeroColor, edgeMask: .noImage, edgeHeight: .init(lower: 0, preferredVw: 0, fixed: 0, upper: 0), textureMask: .noImage, textureSize: [], accentImage: .noImage, scrim: .noImage)
        )
    }()
}

extension ThemeTokensJSON {
    static let fallback: ThemeTokensJSON = {
        let data = Data(fallbackTokensJSON.utf8)
        do {
            return try JSONDecoder().decode(ThemeTokensJSON.self, from: data)
        } catch {
            AlmadarThemeLog.warn("fallback tokens failed to decode: \(error)")
            return ThemeTokensJSON(color: nil, density: nil, typeScale: nil, motion: nil, iconography: nil, elevation: nil, geometry: nil, surface: nil, illustration: nil, colors: nil, radii: nil, spacing: nil, typography: nil, shadows: nil)
        }
    }()
}

