// MARK: - Environment plumbing

private struct AlmadarThemeEnvironmentKey: EnvironmentKey {
    static let defaultValue: AlmadarTheme = .fallback
}

extension EnvironmentValues {
    var almadarTheme: AlmadarTheme {
        get { self[AlmadarThemeEnvironmentKey.self] }
        set { self[AlmadarThemeEnvironmentKey.self] = newValue }
    }
}

/// The host's theme-mode control, the native twin of the web `useTheme()` context (`resolvedMode`,
/// `toggleMode`). `toggle` asks the kernel for the opposite mode and re-resolves the theme.
struct AlmadarThemeModeControl {
    let isDark: Bool
    let toggle: () -> Void
    static let inert = AlmadarThemeModeControl(isDark: false, toggle: {})
}

private struct AlmadarThemeModeEnvironmentKey: EnvironmentKey {
    static let defaultValue: AlmadarThemeModeControl = .inert
}

extension EnvironmentValues {
    var almadarThemeMode: AlmadarThemeModeControl {
        get { self[AlmadarThemeModeEnvironmentKey.self] }
        set { self[AlmadarThemeModeEnvironmentKey.self] = newValue }
    }
}
